import React, { useState } from 'react';

function ConnectedBanks() {
  const [banks, setBanks] = useState([]);
  const [connecting, setConnecting] = useState(false);

  const handleConnectBank = () => {
    setConnecting(true);
    // Placeholder for bank connection flow
    setTimeout(() => {
      setConnecting(false);
      alert('Bank connection feature coming soon. This will integrate with secure banking APIs.');
    }, 1000);
  };

  return (
    <div className="connected-banks-container" style={{ padding: '20px' }}>
      <h2>🏦 Connected Banks</h2>
      <p>Link your bank accounts for seamless financial integration.</p>
      
      <div style={{ marginTop: '20px' }}>
        {banks.length === 0 ? (
          <div style={{ 
            padding: '40px', 
            background: '#1a1a2e', 
            borderRadius: '12px',
            textAlign: 'center',
            border: '2px dashed #333'
          }}>
            <p style={{ color: '#888', marginBottom: '20px' }}>
              No bank accounts connected yet.
            </p>
            <button
              onClick={handleConnectBank}
              disabled={connecting}
              style={{
                padding: '12px 24px',
                background: 'linear-gradient(135deg, #667eea, #764ba2)',
                color: 'white',
                border: 'none',
                borderRadius: '8px',
                cursor: connecting ? 'wait' : 'pointer',
                fontSize: '16px',
                fontWeight: '600'
              }}
            >
              {connecting ? 'Connecting...' : '+ Connect Bank Account'}
            </button>
          </div>
        ) : (
          <div>
            {banks.map((bank, index) => (
              <div 
                key={index}
                style={{ 
                  padding: '16px', 
                  background: '#1a1a2e', 
                  borderRadius: '12px',
                  marginBottom: '12px',
                  border: '1px solid #333'
                }}
              >
                <h3>{bank.name}</h3>
                <p>Account: •••• {bank.lastFour}</p>
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={{ 
        marginTop: '30px', 
        padding: '16px', 
        background: '#16213e', 
        borderRadius: '8px',
        border: '1px solid #1a1a2e'
      }}>
        <h4 style={{ color: '#4ecdc4', margin: '0 0 8px 0' }}>🔒 Security Note</h4>
        <p style={{ color: '#888', fontSize: '14px', margin: 0 }}>
          Bank connections use industry-standard encryption and OAuth 2.0 authentication. 
          We never store your login credentials.
        </p>
      </div>
    </div>
  );
}

export default ConnectedBanks;
